inline bool nonblank(const std::string&s){return std::any_of(s.begin(),s.end(),[](unsigned char c){return !std::isspace(c);});}
inline std::string read_text(const fs::path& p){std::ifstream f(p,std::ios::binary);require(bool(f),"Missing file "+p.string());return {std::istreambuf_iterator<char>(f),std::istreambuf_iterator<char>()};}
